package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.node.ObjectNode;
import dev.dual.core.execution.ArtifactContractResult;
import dev.dual.core.execution.AgentResultContractResult;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Pattern;

public final class ArtifactContractValidator {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };
    private final AgentResultEnvelopeParser resultParser = new AgentResultEnvelopeParser();
    private final AgentResultEnvelopeValidator resultValidator = new AgentResultEnvelopeValidator();
    private final AgentResultDocumentProjector resultProjector = new AgentResultDocumentProjector();
    private final TaskContractRevisionContextResolver revisionContextResolver =
            new TaskContractRevisionContextResolver();
    private final TaskContractProposalRevisionMerger revisionMerger =
            new TaskContractProposalRevisionMerger();

    public NodeResult validate(Path workspaceRoot, NodeDefinition nodeDefinition, NodeResult result) throws Exception {
        return validate(workspaceRoot, "", "", nodeDefinition, List.of(), result);
    }

    public NodeResult validate(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            NodeResult result
    ) throws Exception {
        return validate(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, List.of(), result);
    }

    public NodeResult validate(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            List<String> inputRefs,
            NodeResult result
    ) throws Exception {
        if (AgentExecutionResultFacts.inputPreparationFailed(result)) return result;
        if (EvidenceCollection.FAILURE.equals(result.outcome())) return result;
        if (!"acpx.agent_run".equals(nodeDefinition.handlerType()) || Boolean.TRUE.equals(result.result().get("prepared"))) {
            return result;
        }
        try {
            EvidenceCollection.verify(workspaceRoot, workstreamId, nodeInstanceId);
        } catch (java.io.IOException | IllegalArgumentException invalid) {
            return new NodeResult(EvidenceCollection.FAILURE, dev.dual.core.workflow.NodeStatus.FAILED, List.of(),
                    Map.of("failure_code", EvidenceCollection.FAILURE, "error", String.valueOf(invalid.getMessage())),
                    invalid.getMessage());
        }
        if (!ContractRegistry.hasContract(nodeDefinition.id())) {
            return result;
        }
        var acquisitionContract = AgentExecutionResultFacts.agentResultContract(result);
        if (acquisitionContract.present() && !acquisitionContract.valid()) {
            // Re-parsing a well-formed final candidate must not erase the acquisition's stricter diff rejection.
            return contractViolation(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, result,
                    ContractRegistry.forNode(nodeDefinition.id()), "", null,
                    ContractViolation.of("AGENT_RESULT_CONTRACT_VIOLATION", acquisitionContract.validationError(), Map.of()));
        }
        return validateAgentOutput(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, inputRefs, result);
    }

    private NodeResult validateAgentOutput(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            List<String> inputRefs,
            NodeResult result
    ) throws Exception {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var contract = ContractRegistry.forNode(nodeDefinition.id());
        ContractViolation lastInvalid = null;
        String lastSourceRef = "";
        var repositoryFactBindingRef = text(result.result().get("repository_fact_binding_ref"));
        for (int i = result.outputRefs().size() - 1; i >= 0; i--) {
            var ref = result.outputRefs().get(i);
            if (ref.startsWith("artifact://")
                    || !ref.endsWith(".json")
                    || ref.equals(repositoryFactBindingRef)) {
                continue;
            }
            var path = root.resolve(ref).normalize();
            if (!path.startsWith(root) || !Files.isRegularFile(path)) {
                continue;
            }
            var candidate = Files.readString(path, StandardCharsets.UTF_8);
            var parsed = resultParser.parse(candidate);
            if (!parsed.valid()) {
                lastInvalid = ContractViolation.of(parsed.errorCode(), parsed.message(), Map.of());
                lastSourceRef = ref;
                break;
            }
            var expectedRunId = text(result.result().get("run_id"));
            var validation = resultValidator.validate(parsed.envelope(), workstreamId, expectedRunId, contract);
            if (!validation.valid()) {
                lastInvalid = ContractViolation.of(
                        "AGENT_RESULT_CONTRACT_VIOLATION",
                        "AgentResultEnvelope failed contract validation: " + validation.errors(),
                        Map.of("errors", validation.errors())
                );
                lastSourceRef = ref;
                break;
            }
            try {
                EvidenceCollection.verifyResult(root, workstreamId, nodeInstanceId, parsed.envelope().result());
            } catch (java.io.IOException | IllegalArgumentException invalid) {
                return new NodeResult(EvidenceCollection.FAILURE, dev.dual.core.workflow.NodeStatus.FAILED, List.of(),
                        Map.of("failure_code", EvidenceCollection.FAILURE, "error", String.valueOf(invalid.getMessage())), invalid.getMessage());
            }
            if (parsed.envelope().result() instanceof AgentResultEnvelope.DesignResult design) {
                var errors = DesignScopeValidator.validate(root, workstreamId, design.design());
                if (!errors.isEmpty()) {
                    return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, ref,
                            parsed.envelope(), ContractViolation.of("DESIGN_SCOPE_INVALID",
                                    "Design is not within the approved contract", Map.of("errors", errors)));
                }
            }
            if (parsed.envelope().result() instanceof AgentResultEnvelope.PlanResult plan) {
                var errors = PlanScopeValidator.validate(root, workstreamId, plan.plan());
                if (!errors.isEmpty()) {
                    return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, ref,
                            parsed.envelope(), ContractViolation.of("PLAN_SCOPE_INVALID",
                                    "Plan is not within the approved contract", Map.of("errors", errors)));
                }
            }
            var repositoryFactBinding = resolveRepositoryFactBinding(
                    root, workstreamId, nodeInstanceId, expectedRunId, result);
            var proposalResolution = resolveProposalCandidate(
                    root, workstreamId, nodeInstanceId, nodeDefinition, parsed.envelope(), ref,
                    repositoryFactBinding);
            if (proposalResolution.failure() != null) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, ref,
                        parsed.envelope(), proposalResolution.failure());
            }
            return withResultSidecars(
                    root, workstreamId, nodeInstanceId, nodeDefinition, inputRefs, result, contract,
                    parsed.envelope(), ref, path, proposalResolution
            );
        }
        return contractViolation(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, result, contract,
                lastSourceRef, null, lastInvalid);
    }

    private ProposalResolution resolveProposalCandidate(
            Path root,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            AgentResultEnvelope envelope,
            String sourceOutputRef,
            RepositoryFactBinding.Verification repositoryFactBinding
    ) {
        var isProposal = envelope.result() instanceof AgentResultEnvelope.TaskContractProposalResult;
        var isPatch = envelope.result() instanceof AgentResultEnvelope.TaskContractRevisionPatchResult;
        if (!isProposal && !isPatch) {
            return ProposalResolution.none();
        }
        if (!repositoryFactBinding.valid()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_REPOSITORY_FACT_BINDING_INVALID",
                    "task contract proposal has no valid repository fact occurrence binding",
                    Map.of("errors", repositoryFactBinding.errors())));
        }
        if (!"intake.claude_brainstorm".equals(nodeDefinition.id())) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_PROPOSAL_INVALID",
                    "task contract proposal output is only allowed for intake",
                    Map.of()));
        }
        var resolved = revisionContextResolver.resolveForNode(root, workstreamId, nodeInstanceId);
        if (!resolved.valid()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_REVISION_CONTEXT_INVALID",
                    "task contract proposal revision context could not be resolved",
                    Map.of("errors", resolved.errors())));
        }
        var context = resolved.context();
        TaskContractProposal proposal;
        AgentOutputContractDocument.ProposalDerivation derivation = null;
        if (isProposal) {
            if (context.revision()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_SHAPE_INVALID",
                        "revision iteration requires task_contract_revision_patch",
                        Map.of()));
            }
            var proposalResult = (AgentResultEnvelope.TaskContractProposalResult) envelope.result();
            var resolvedScope = new TaskContractScopeResolver().resolve(
                    proposalResult.scope().included(), root);
            if (!resolvedScope.valid()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_SCOPE_RESOLUTION_FAILED",
                        "task contract scope paths could not be resolved",
                        Map.of("errors", resolvedScope.errors())));
            }
            proposal = resultProjector.taskContractProposal(proposalResult, resolvedScope.entries());
        } else {
            if (!context.revision()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_SHAPE_INVALID",
                        "initial iteration requires task_contract_proposal",
                        Map.of()));
            }
            var merged = revisionMerger.merge(
                    context, (AgentResultEnvelope.TaskContractRevisionPatchResult) envelope.result(), root);
            if (!merged.valid()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_PATCH_INVALID",
                        "task contract revision patch could not be merged",
                        Map.of("errors", merged.errors())));
            }
            proposal = merged.proposal();
            derivation = new AgentOutputContractDocument.ProposalDerivation(
                    "revision_patch_merge",
                    context.previousReference().proposalId(),
                    context.previousReference().sha256(),
                    context.previousReference(),
                    sourceOutputRef);
        }

        var proposalValidator = new TaskContractProposalValidator();
        var errors = proposalValidator.validate(proposal, root,
                context.approvedScopeBaseline(), context.originalBaseCommit(), context.scopeReviewCandidates());
        if (!errors.isEmpty()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_PROPOSAL_VALIDATION_FAILED",
                    "task_contract_proposal failed mechanical validation: " + errors,
                    Map.of("errors", errors)));
        }
        var coverageErrors = context.revision()
                ? proposalValidator.validateRevisionCoverage(proposal, context.obligations())
                : proposalValidator.validateInitialIteration(proposal);
        if (!coverageErrors.isEmpty()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_REVISION_COVERAGE_INVALID",
                    "task_contract_proposal failed revision obligation coverage",
                    Map.of("errors", coverageErrors)));
        }
        var evidenceErrors = proposalValidator.validateEvidenceTraceability(
                proposal, root, repositoryFactBinding.verified());
        if (!evidenceErrors.isEmpty()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_EVIDENCE_TRACEABILITY_INVALID",
                    "task_contract_proposal is not grounded in the tracked inventory",
                    Map.of("errors", evidenceErrors)));
        }
        if (context.revision()) {
            var deltaErrors = proposalValidator.validateRevisionDelta(context.previousProposal(), proposal);
            if (!deltaErrors.isEmpty()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_DELTA_INVALID",
                        "task_contract_proposal contains an invalid revision delta",
                        Map.of(
                                "error_codes", deltaErrors.stream()
                                        .map(TaskContractProposalValidator.RevisionDeltaError::code).distinct().toList(),
                                "errors", deltaErrors.stream()
                                        .map(TaskContractProposalValidator.RevisionDeltaError::message).toList())));
            }
        }
        return new ProposalResolution(proposal, derivation, repositoryFactBinding.verified(), null);
    }

    private NodeResult withResultSidecars(
            Path root,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            List<String> inputRefs,
            NodeResult result,
            NodeOutputContract contract,
            AgentResultEnvelope envelope,
            String outputRef,
            Path outputPath,
            ProposalResolution proposalResolution
    ) throws Exception {
        var document = resultProjector.outputContract(
                envelope, contract, nodeDefinition.handlerType(), nodeInstanceId, outputRef,
                proposalResolution.proposal(), proposalResolution.derivation());
        var requiredReviewSubject = text(nodeDefinition.config().get("review_subject_artifact"));
        if (!requiredReviewSubject.isBlank()) {
            if (!"task_contract_proposal".equals(requiredReviewSubject)) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                        envelope,
                        ContractViolation.of("REVIEW_SUBJECT_UNSUPPORTED",
                                "unsupported review_subject_artifact: " + requiredReviewSubject,
                                Map.of("review_subject_artifact", requiredReviewSubject)));
            }
            var reviewSubject = TaskContractProposalReference.resolveFromRefs(
                    root, workstreamId, inputRefs, OBJECT_MAPPER);
            if (reviewSubject.isEmpty()) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                        envelope,
                        ContractViolation.of("REVIEW_SUBJECT_MISSING",
                                "exactly one validated task_contract_proposal reference is required",
                                Map.of("review_subject_artifact", requiredReviewSubject)));
            }
            document.put("review_subject", reviewSubject.get().reference().toMap());
        }
        if (proposalResolution.proposal() != null) {
            document.put("repository_fact_binding",
                    RepositoryFactBinding.reference(proposalResolution.repositoryFactBinding()).toMap());
        }
        AgentContractSemantics.addSidecarFields(document);
        var validatedDocument = AgentOutputContractDocument.from(document);
        var semanticFailure = AgentContractSemantics.validateOutputContract(validatedDocument);
        if (semanticFailure.isPresent()) {
            return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                    envelope,
                    semanticFailure.get());
        }

        var publication = AgentExecutionResultFacts.attach(result,
                AgentResultContractResult.valid(envelope.result().decision()),
                List.of(ArtifactContractResult.requiredValid(envelope.result().artifactType())),
                document.get("reread_reasons"));
        var execution = new AgentRunMetadataFinalizer().assessPublication(root, publication);
        if (execution.status() == NodeStatus.FAILED) {
            return AgentExecutionResultFacts.attach(execution,
                    AgentResultContractResult.valid(envelope.result().decision()),
                    List.of(new ArtifactContractResult(envelope.result().artifactType(), true, false, false, "",
                            "EXECUTION_NOT_PUBLISHABLE", "Execution failed before artifact publication")),
                    document.get("reread_reasons"));
        }

        var sidecarPath = AgentOutputContractSidecar.pathFor(outputPath);
        if (AuthoredStageLineageResolver.participates(nodeDefinition.id())) {
            try {
                var authoredRef = AuthoredExecutionContext.validatePublication(root, workstreamId, nodeInstanceId,
                        envelope.runId(), envelope.result());
                document.put("authored_context", Map.of("ref", authoredRef.ref(), "sha256", authoredRef.sha256()));
            } catch (java.io.IOException | IllegalArgumentException failure) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                        envelope, ContractViolation.of("AUTHORED_CONTEXT_INVALID", failure.getMessage(), Map.of()));
            }
        }
        try {
            EvidenceCollection.verifyResult(root, workstreamId, nodeInstanceId, envelope.result());
        } catch (java.io.IOException | IllegalArgumentException invalid) {
            return new NodeResult(EvidenceCollection.FAILURE, dev.dual.core.workflow.NodeStatus.FAILED, List.of(),
                    Map.of("failure_code", EvidenceCollection.FAILURE, "error", String.valueOf(invalid.getMessage())), invalid.getMessage());
        }
        Files.writeString(sidecarPath,
                OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(document) + "\n",
                StandardCharsets.UTF_8);
        var sidecarRef = root.relativize(sidecarPath).toString();
        var outputRefs = new ArrayList<>(result.outputRefs());
        if (!outputRefs.contains(sidecarRef)) {
            outputRefs.add(sidecarRef);
        }

        Optional<TaskContractProposalReference.Published> proposalReference = Optional.empty();
        if (proposalResolution.proposal() != null) {
            proposalReference = Optional.of(
                    envelope.result() instanceof AgentResultEnvelope.TaskContractRevisionPatchResult
                            ? TaskContractProposalReference.publishRevisionDerived(
                            root, workstreamId, sidecarPath, validatedDocument, OBJECT_MAPPER)
                            : TaskContractProposalReference.publishInitial(
                            root, workstreamId, sidecarPath, validatedDocument, OBJECT_MAPPER));
            if (!outputRefs.contains(proposalReference.get().referenceRef())) {
                outputRefs.add(proposalReference.get().referenceRef());
            }
        }

        var planArtifactRef = writePlanArtifactSidecars(
                root, envelope, outputPath);
        planArtifactRef.ifPresent(ref -> {
            if (!outputRefs.contains(ref)) {
                outputRefs.add(ref);
            }
        });

        var augmented = new LinkedHashMap<String, Object>();
        augmented.putAll(result.result());
        augmented.put("decision", envelope.result().decision());
        augmented.put("summary", envelope.result().summary());
        augmented.put("contract_sidecar_ref", sidecarRef);
        augmented.put("contract_sidecar_sha256", AgentOutputContractSidecar.sha256(sidecarPath));
        proposalReference.ifPresent(reference -> {
            augmented.put("task_contract_proposal_ref", reference.referenceRef());
            augmented.put("task_contract_proposal_id", reference.reference().proposalId());
        });
        planArtifactRef.ifPresent(ref -> augmented.put("plan_artifact_ref", ref));
        return AgentExecutionResultFacts.attach(new NodeResult(
                        result.outcome(), result.status(), outputRefs, augmented, result.errorMessage()),
                AgentResultContractResult.valid(envelope.result().decision()),
                List.of(ArtifactContractResult.requiredValid(envelope.result().artifactType())),
                document.get("reread_reasons"));
    }

    private record ProposalResolution(
            TaskContractProposal proposal,
            AgentOutputContractDocument.ProposalDerivation derivation,
            RepositoryFactBinding.Verified repositoryFactBinding,
            ContractViolation failure
    ) {
        static ProposalResolution none() {
            return new ProposalResolution(null, null, null, null);
        }

        static ProposalResolution failure(ContractViolation failure) {
            return new ProposalResolution(null, null, null, failure);
        }
    }

    private RepositoryFactBinding.Verification resolveRepositoryFactBinding(
            Path root,
            String workstreamId,
            String nodeInstanceId,
            String runId,
            NodeResult result
    ) {
        var bindingRef = text(result.result().get("repository_fact_binding_ref"));
        var bindingSha256 = text(result.result().get("repository_fact_binding_sha256"));
        if (bindingRef.isBlank() || bindingSha256.isBlank() || !result.outputRefs().contains(bindingRef)) {
            return new RepositoryFactBinding.Verification(
                    null,
                    List.of("adapter-owned repository fact binding ref/sha is missing or not routed"));
        }
        return RepositoryFactBinding.verify(
                root,
                workstreamId,
                bindingRef,
                bindingSha256,
                nodeInstanceId,
                runId,
                OBJECT_MAPPER);
    }

    private Optional<String> writePlanArtifactSidecars(
            Path root,
            AgentResultEnvelope envelope,
            Path outputPath
    ) throws Exception {
        if (!(envelope.result() instanceof AgentResultEnvelope.PlanResult planResult)) {
            return Optional.empty();
        }
        var document = resultProjector.planArtifact(planResult);
        var sidecarPath = PlanArtifactSidecar.pathFor(outputPath);
        Files.writeString(sidecarPath,
                OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(document) + "\n",
                StandardCharsets.UTF_8);
        return Optional.of(root.relativize(sidecarPath).toString());
    }

    private static List<String> stringList(Object value) {
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        return list.stream()
                .filter(item -> item != null && !String.valueOf(item).isBlank())
                .map(item -> String.valueOf(item).trim())
                .toList();
    }

    private static String normalizeRepoPath(String value) {
        var text = value == null ? "" : value.trim();
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        return text;
    }

    private static NodeResult contractViolation(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            NodeResult result,
            NodeOutputContract contract,
            String sourceOutputRef,
            AgentResultEnvelope validatedEnvelope,
            ContractViolation lastInvalid
    ) throws Exception {
        var reason = lastInvalid == null
                ? "AGENT_RESULT_MISSING"
                : lastInvalid.errorCode();
        var message = lastInvalid == null
                ? "No readable agent output artifact found for contract validation."
                : lastInvalid.message();
        var details = lastInvalid == null ? Map.<String, Object>of() : lastInvalid.details();
        var diagnostic = ContractFailureDiagnosticWriter.write(
                workspaceRoot,
                workstreamId,
                nodeInstanceId,
                nodeDefinition,
                contract,
                sourceOutputRef,
                reason,
                message,
                details
        );
        var failed = new LinkedHashMap<String, Object>();
        failed.putAll(result.result());
        failed.put("reason", "AGENT_OUTPUT_CONTRACT_VIOLATION");
        failed.put("contract_node_id", nodeDefinition.id());
        failed.put("contract_required_keys", List.copyOf(contract.requiredKeys()));
        failed.put("contract_allowed_decisions", List.copyOf(contract.allowedDecisions()));
        failed.put("parse_error", Map.of(
                "code", reason,
                "message", message,
                "details", details
        ));
        if (diagnostic.present()) {
            failed.put("contract_failure_diagnostic_ref", diagnostic.jsonRef());
            failed.put("contract_failure_diagnostic_markdown_ref", diagnostic.markdownRef());
        }
        failed.put("message", message);
        var outputRefs = new ArrayList<>(result.outputRefs());
        if (diagnostic.present() && !outputRefs.contains(diagnostic.jsonRef())) {
            outputRefs.add(diagnostic.jsonRef());
        }
        if (diagnostic.present() && !outputRefs.contains(diagnostic.markdownRef())) {
            outputRefs.add(diagnostic.markdownRef());
        }
        return AgentExecutionResultFacts.attach(new NodeResult(
                "AGENT_OUTPUT_CONTRACT_VIOLATION",
                NodeStatus.FAILED,
                outputRefs,
                failed,
                message
        ), terminalResultFor(reason, message, validatedEnvelope),
                List.of(artifactResultFor(nodeDefinition, reason, message, validatedEnvelope)), null);
    }

    private static AgentResultContractResult terminalResultFor(
            String reason,
            String message,
            AgentResultEnvelope validatedEnvelope
    ) {
        if (validatedEnvelope != null) {
            return AgentResultContractResult.valid(validatedEnvelope.result().decision());
        }
        if (reason == null || reason.isBlank() || "AGENT_RESULT_MISSING".equals(reason)) {
            return AgentResultContractResult.missing();
        }
        return AgentResultContractResult.invalid(message);
    }

    private static ArtifactContractResult artifactResultFor(
            NodeDefinition nodeDefinition,
            String reason,
            String message,
            AgentResultEnvelope validatedEnvelope
    ) {
        if (validatedEnvelope != null) {
            return new ArtifactContractResult(
                    requiredArtifactTypeOrDefault(nodeDefinition),
                    true,
                    true,
                    false,
                    "",
                    reason,
                    message
            );
        }
        if (reason != null && (reason.startsWith("AGENT_RESULT_") && !"AGENT_RESULT_MISSING".equals(reason))) {
            return new ArtifactContractResult(
                    requiredArtifactTypeOrDefault(nodeDefinition),
                    true,
                    false,
                    false,
                    "",
                    reason,
                    message
            );
        }
        return ArtifactContractResult.optionalMissing(requiredArtifactTypeOrDefault(nodeDefinition));
    }

    private static String requiredArtifactType(NodeDefinition nodeDefinition) {
        var configured = text(nodeDefinition.config().get("expected_artifact"));
        if (!configured.isBlank()) {
            return configured;
        }
        var contract = ContractRegistry.forNode(nodeDefinition.id());
        return contract.outputArtifactTypes().size() == 1
                ? contract.outputArtifactTypes().iterator().next()
                : "agent_output_contract";
    }

    private static String requiredArtifactTypeOrDefault(NodeDefinition nodeDefinition) {
        var required = requiredArtifactType(nodeDefinition);
        return required == null || required.isBlank() ? "agent_output_contract" : required;
    }

    private static Optional<Path> resolveWorkspaceRef(Path root, String ref) {
        if (ref == null || ref.isBlank()) {
            return Optional.empty();
        }
        var path = root.resolve(ref).normalize();
        if (!path.startsWith(root)) {
            return Optional.empty();
        }
        return Optional.of(path);
    }

    private static Object fieldOrLegacy(ObjectNode node, String field, String legacyField) {
        if (node.has(field)) {
            return OBJECT_MAPPER.convertValue(node.get(field), Object.class);
        }
        return OBJECT_MAPPER.convertValue(node.path(legacyField), Object.class);
    }

    private static String firstNonBlank(String first, String second) {
        return firstNonBlank(new String[]{first, second});
    }

    private static String firstNonBlank(String... values) {
        if (values == null) {
            return "";
        }
        for (var value : values) {
            if (value != null && !value.isBlank()) {
                return value;
            }
        }
        return "";
    }

    private static Optional<Map<String, Object>> readMap(Path path) {
        try {
            return Optional.of(OBJECT_MAPPER.readValue(path.toFile(), MAP_TYPE));
        } catch (Exception ignored) {
            return Optional.empty();
        }
    }

    private static List<String> capabilityKinds(ObjectNode report) {
        var values = new LinkedHashSet<String>();
        for (var item : mapList(OBJECT_MAPPER.convertValue(report.path("actualCapabilityUsages"), Object.class))) {
            var kind = text(item.get("kind"));
            if (!kind.isBlank()) {
                values.add(kind);
            }
        }
        return List.copyOf(values);
    }

    private static List<Map<String, Object>> mapList(Object value) {
        if (!(value instanceof Iterable<?> iterable)) {
            return List.of();
        }
        var values = new ArrayList<Map<String, Object>>();
        for (var item : iterable) {
            if (!(item instanceof Map<?, ?> map)) {
                continue;
            }
            var copy = new LinkedHashMap<String, Object>();
            for (var entry : map.entrySet()) {
                if (entry.getKey() instanceof String key) {
                    copy.put(key, entry.getValue());
                }
            }
            values.add(copy);
        }
        return List.copyOf(values);
    }

    private static Map<String, String> stringMap(Object value) {
        if (!(value instanceof Map<?, ?> map)) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, String>();
        for (var entry : map.entrySet()) {
            if (entry.getKey() instanceof String key && entry.getValue() != null) {
                var text = String.valueOf(entry.getValue()).trim();
                if (!text.isBlank()) {
                    copy.put(key, text);
                }
            }
        }
        return Map.copyOf(copy);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

}

package dev.dual.runtime;

import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.core.workflow.WorkflowStatus;
import dev.dual.ledger.file.NodeExecutionStatus;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowExecutionStatus;
import dev.dual.ledger.file.WorkflowExecutionDocument;
import dev.dual.ledger.file.WorkflowCurrentDocument;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;
import dev.dual.runtime.handler.AgentExecutionAttemptReconciler;
import dev.dual.runtime.handler.AgentExecutionAttemptTimeoutPolicy;
import dev.dual.runtime.handler.AgentRunMetadataFinalizer;
import dev.dual.runtime.handler.ArtifactContractValidator;
import dev.dual.runtime.handler.ContractEventTypes;
import dev.dual.runtime.handler.DecisionHandler;
import dev.dual.runtime.handler.GateHandler;
import dev.dual.runtime.handler.HandlerRegistry;
import dev.dual.runtime.handler.TaskHandler;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Drives one workflow instance forward from the authoritative ledger state.
 *
 * Runtime owns transition execution and runtime facts only: it creates workflow
 * and node execution records, invokes handlers, validates artifact contracts,
 * and asks the ledger to route completed nodes. It must not infer product goal
 * satisfaction from prose, and it must guard terminal workflows before creating
 * any new execution side effects.
 */
public final class WorkflowRuntime {
    private final WorkflowFileLedger ledger;
    private final HandlerRegistry handlers;
    private final ArtifactContractValidator artifactContractValidator;
    private final AgentRunMetadataFinalizer runMetadataFinalizer;
    private final AgentExecutionAttemptReconciler attemptReconciler;
    private final StaleRunningRecovery staleRunningRecovery;
    private final AgentTaskDispatchMode dispatchMode;

    public WorkflowRuntime(WorkflowFileLedger ledger, HandlerRegistry handlers) {
        this(ledger, handlers, AgentTaskDispatchMode.INLINE);
    }

    public WorkflowRuntime(WorkflowFileLedger ledger, HandlerRegistry handlers, AgentTaskDispatchMode dispatchMode) {
        if (ledger == null) {
            throw new IllegalArgumentException("ledger is required");
        }
        if (handlers == null) {
            throw new IllegalArgumentException("handlers is required");
        }
        this.ledger = ledger;
        this.handlers = handlers;
        this.dispatchMode = dispatchMode == null ? AgentTaskDispatchMode.INLINE : dispatchMode;
        this.artifactContractValidator = new ArtifactContractValidator();
        this.runMetadataFinalizer = new AgentRunMetadataFinalizer();
        this.attemptReconciler = new AgentExecutionAttemptReconciler(new AgentExecutionAttemptTimeoutPolicy().timeout());
        this.staleRunningRecovery = new StaleRunningRecovery(ledger, attemptReconciler);
    }

    /**
     * Advances the current workflow until it reaches a gate, recovery boundary,
     * terminal state, or the current active-node snapshot is exhausted.
     *
     * Key steps:
     * 1. Load definition/current from the ledger.
     * 2. Refuse terminal workflows before creating a workflow execution.
     * 3. Create a workflow execution and per-node execution/task records.
     * 4. Execute handlers and validate structured artifacts.
     * 5. Finish the workflow execution with a typed runtime status.
     */
    public WorkflowRuntimeResult resume(WorkflowCommand command) throws Exception {
        var paths = new WorkstreamPaths(command.workspaceRoot(), new DualId(command.workstreamId()));
        var definition = ledger.loadDefinition(paths);
        var current = ledger.loadCurrent(paths);

        // Terminal observation is allowed elsewhere, but resume must be side-effect free.
        if (current.status().isTerminal()) {
            return new WorkflowRuntimeResult(
                    command.workstreamId(),
                    current.status(),
                    "",
                    "workflow is terminal: " + current.status()
            );
        }
        // Reconcile any in-flight agent run for the active node whose transport
        // never returned before this resume creates new execution side effects.
        // If a run is reconciled, stop at recovery instead of creating another
        // attempt for the same node.
        var reconciled = reconcileActiveNodeAttempts(command, paths, definition, current);
        if (reconciled != null) {
            return reconciled;
        }

        var workflowExecution = ledger.startWorkflowExecution(paths, current, "resume");
        var nodeExecutionIds = new ArrayList<String>();
        var workflowExecutionFinished = false;
        try {
            var outcome = resumeWithinExecution(command, paths, definition, current, workflowExecution, nodeExecutionIds);
            var finalResult = outcome.result();
            finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, outcome.executionStatus(), finalResult.message());
            workflowExecutionFinished = true;
            return finalResult;
        } catch (Exception failure) {
            if (!workflowExecutionFinished) {
                finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, WorkflowExecutionStatus.FAILED, failure.getMessage());
            }
            throw failure;
        }
    }

    private ResumeOutcome resumeWithinExecution(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds
    ) throws Exception {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return stopped(new WorkflowRuntimeResult(command.workstreamId(), current.status(), "", "workflow has no active node"));
        }
        if (current.status() == WorkflowStatus.WAITING_FOR_RECOVERY) {
            var recoveryRejection = rejectRecoveryOrAutoRetry(command, paths, definition, current);
            if (recoveryRejection != null) {
                return stopped(recoveryRejection);
            }
            current = ledger.loadCurrent(paths);
        }
        var result = executeActiveSnapshot(command, paths, definition, current, workflowExecution, nodeExecutionIds);
        return new ResumeOutcome(result, workflowExecutionStatus(result.status()));
    }

    private WorkflowRuntimeResult reconcileActiveNodeAttempts(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current
    ) throws Exception {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return null;
        }
        for (var activeNodeId : current.activeNodeInstanceIds()) {
            var node = ledger.loadNode(paths, activeNodeId);
            var count = attemptReconciler.reconcileRuns(paths.runsDir(), node.nodeDefinitionId());
            if (count <= 0) {
                continue;
            }
            if (node.status() == NodeStatus.RUNNING) {
                recoverStaleRunningNode(paths, node, node.result().getOrDefault("running_pid", ""));
            } else {
                ledger.completeAndRoute(
                        paths,
                        definition,
                        node.nodeInstanceId(),
                        NodeStatus.FAILED,
                        "STALE_RUNNING_ATTEMPT",
                        node.outputRefs(),
                        Map.of(
                                "reason", "STALE_RUNNING_ATTEMPT",
                                "message", "A previous agent execution attempt was reconciled to a typed terminal outcome before resume.",
                                "recoverable", true,
                                "reconciled_attempt_count", count
                        )
                );
            }
            var next = ledger.loadCurrent(paths);
            return new WorkflowRuntimeResult(
                    command.workstreamId(),
                    next.status(),
                    activeNodeDefinitionId(paths, next),
                    "workflow stopped at reconciled stale agent execution"
            );
        }
        return null;
    }

    private WorkflowRuntimeResult rejectRecoveryOrAutoRetry(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current
    ) throws Exception {
        var nodeDoc = ledger.loadNode(paths, current.activeNodeInstanceIds().get(0));
        var nodeDef = definition.node(nodeDoc.nodeDefinitionId());
        if (nodeDoc.status() == NodeStatus.FAILED && attemptAutoRetry(paths, nodeDoc, nodeDef)) {
            return null;
        }
        return rejectionResult(command, current, nodeDoc, nodeDef);
    }

    private WorkflowRuntimeResult executeActiveSnapshot(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds
    ) throws Exception {
        var activeSnapshot = new ArrayList<>(current.activeNodeInstanceIds());
        WorkflowRuntimeResult lastResult = null;

        for (var activeNodeId : activeSnapshot) {
            current = ledger.loadCurrent(paths);
            if (current.activeNodeInstanceIds().isEmpty()) {
                break;
            }
            if (!current.activeNodeInstanceIds().contains(activeNodeId)) {
                continue;
            }
            lastResult = executeActiveNode(command, paths, definition, workflowExecution, nodeExecutionIds, activeNodeId);
        }
        return lastResult != null
                ? lastResult
                : new WorkflowRuntimeResult(command.workstreamId(), current.status(), "", "workflow has no active node");
    }

    private WorkflowRuntimeResult executeActiveNode(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds,
            String activeNodeId
    ) throws Exception {
        var nodeDoc = ledger.loadNode(paths, activeNodeId);
        var nodeDefinition = definition.node(nodeDoc.nodeDefinitionId());

        if (nodeDefinition.kind() == NodeKind.GATE) {
            var node = ledger.loadCoreNode(paths, activeNodeId);
            handlers.gate(nodeDefinition.handlerType())
                    .openOrInspect(new GateHandler.GateContext(
                            command.workspaceRoot(), command.workstreamId(), nodeDefinition, node,
                            sourceOutcome(paths, activeNodeId)));
            return new WorkflowRuntimeResult(command.workstreamId(), WorkflowStatus.WAITING_FOR_HUMAN, nodeDefinition.id(), "waiting for human review");
        }

        var guardResult = resolveNodeForExecution(paths, nodeDoc);
        if (guardResult == null) {
            var refreshedCurrent = ledger.loadCurrent(paths);
            var refreshedNode = ledger.loadNode(paths, activeNodeId);
            var refreshedDefinition = definition.node(refreshedNode.nodeDefinitionId());
            return rejectionResult(command, refreshedCurrent, refreshedNode, refreshedDefinition);
        }

        if (dispatchMode == AgentTaskDispatchMode.WORKER) {
            return enqueueAgentTask(command, paths, workflowExecution, nodeDoc, nodeDefinition);
        }

        var result = executeAndRecordNode(command, paths, workflowExecution, nodeExecutionIds, nodeDoc, nodeDefinition);
        emitDomainEvents(paths, nodeDefinition.id(), nodeDefinition.handlerType(), nodeDoc.nodeInstanceId(), result);
        ledger.completeAndRoute(paths, definition, nodeDoc.nodeInstanceId(), result.status(), result.outcome(), result.outputRefs(), result.result());
        var next = ledger.loadCurrent(paths);
        openWaitingGates(command, paths, definition, next);
        var active = activeNodeDefinitionId(paths, next);
        var message = result.status() == NodeStatus.COMPLETED ? "resumed workflow" : "workflow stopped at " + result.status();
        return new WorkflowRuntimeResult(command.workstreamId(), next.status(), active, message);
    }

    private WorkflowRuntimeResult enqueueAgentTask(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            NodeInstanceDocument nodeDoc,
            NodeDefinition nodeDefinition
    ) throws Exception {
        var agentTask = ledger.createAgentTask(paths, workflowExecution.workflowExecutionId(), nodeDefinition, nodeDoc);
        ledger.markQueuedForAgentTask(paths, nodeDoc.nodeInstanceId(), agentTask.agentTaskId());
        return new WorkflowRuntimeResult(command.workstreamId(), WorkflowStatus.RUNNING, nodeDefinition.id(), "agent task queued");
    }

    private WorkflowRuntimeResult rejectionResult(
            WorkflowCommand command,
            WorkflowCurrentDocument current,
            NodeInstanceDocument node,
            NodeDefinition definition
    ) {
        var rejection = NodeExecutionGuard.reject(node, definition);
        return new WorkflowRuntimeResult(command.workstreamId(), current.status(), node.nodeDefinitionId(), rejection.message());
    }

    private String activeNodeDefinitionId(WorkstreamPaths paths, WorkflowCurrentDocument current) throws Exception {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return "";
        }
        return ledger.loadNode(paths, current.activeNodeInstanceIds().get(0)).nodeDefinitionId();
    }

    private static ResumeOutcome stopped(WorkflowRuntimeResult result) {
        return new ResumeOutcome(result, WorkflowExecutionStatus.STOPPED);
    }

    private record ResumeOutcome(WorkflowRuntimeResult result, WorkflowExecutionStatus executionStatus) {
    }

    private NodeResult executeAndRecordNode(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds,
            NodeInstanceDocument nodeDoc,
            NodeDefinition nodeDefinition
    ) throws Exception {
        long pid = ProcessHandle.current().pid();
        var agentTask = ledger.createAgentTask(paths, workflowExecution.workflowExecutionId(), nodeDefinition, nodeDoc);
        var nodeExecution = ledger.startNodeExecution(paths, workflowExecution.workflowExecutionId(), nodeDoc, agentTask, pid);
        agentTask = ledger.markAgentTaskRunning(paths, agentTask, nodeExecution.nodeExecutionId());
        nodeExecutionIds.add(nodeExecution.nodeExecutionId());
        ledger.markRunning(paths, nodeDoc.nodeInstanceId(), pid);

        var node = ledger.loadCoreNode(paths, nodeDoc.nodeInstanceId());
        try {
            var result = dev.dual.runtime.handler.EvidenceCollection.execute(command.workspaceRoot(),
                    command.workstreamId(), nodeDoc, () -> executeNode(command, nodeDefinition, node));
            result = artifactContractValidator.validate(
                    command.workspaceRoot(),
                    command.workstreamId(),
                    node.nodeInstanceId(),
                    nodeDefinition,
                    node.inputRefs(),
                    result
            );
            result = runMetadataFinalizer.finalizeNodeResult(command.workspaceRoot(), result);
            ledger.markAgentTaskFinished(paths, agentTask, result);
            ledger.finishNodeExecution(paths, nodeExecution, result);
            return result;
        } catch (Exception nodeFailure) {
            ledger.markAgentTaskFailed(paths, agentTask, nodeFailure);
            ledger.failNodeExecution(paths, nodeExecution, nodeFailure);
            throw nodeFailure;
        }
    }

    private NodeResult executeNode(WorkflowCommand command, NodeDefinition nodeDefinition, dev.dual.core.workflow.NodeInstance node) throws Exception {
        return switch (nodeDefinition.kind()) {
            case TASK -> handlers.task(nodeDefinition.handlerType())
                    .execute(new TaskHandler.TaskContext(command.workspaceRoot(), command.workstreamId(), nodeDefinition, node));
            case DECISION -> handlers.decision(nodeDefinition.handlerType())
                    .evaluate(new DecisionHandler.DecisionContext(command.workspaceRoot(), command.workstreamId(), nodeDefinition, node));
            case GATE -> throw new IllegalStateException("gate nodes are handled before routing");
        };
    }

    private void finishWorkflowExecution(
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds,
            WorkflowExecutionStatus status,
            String stopReason
    ) throws Exception {
        ledger.finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, status, stopReason);
    }

    private static WorkflowExecutionStatus workflowExecutionStatus(WorkflowStatus status) {
        return switch (status) {
            case CREATED -> WorkflowExecutionStatus.CREATED;
            case RUNNING -> WorkflowExecutionStatus.STOPPED;
            case WAITING_FOR_HUMAN -> WorkflowExecutionStatus.WAITING_FOR_HUMAN;
            case WAITING_FOR_RECOVERY -> WorkflowExecutionStatus.WAITING_FOR_RECOVERY;
            case BLOCKED -> WorkflowExecutionStatus.BLOCKED;
            case COMPLETED -> WorkflowExecutionStatus.ENDED;
            case FAILED -> WorkflowExecutionStatus.FAILED;
        };
    }

    private void openWaitingGates(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current
    ) throws Exception {
        if (current.status() != WorkflowStatus.WAITING_FOR_HUMAN) {
            return;
        }
        for (var activeNodeId : current.activeNodeInstanceIds()) {
            var nodeDoc = ledger.loadNode(paths, activeNodeId);
            if (nodeDoc.kind() != NodeKind.GATE) {
                continue;
            }
            var nodeDefinition = definition.node(nodeDoc.nodeDefinitionId());
            var node = ledger.loadCoreNode(paths, activeNodeId);
            handlers.gate(nodeDefinition.handlerType())
                    .openOrInspect(new GateHandler.GateContext(
                            command.workspaceRoot(), command.workstreamId(), nodeDefinition, node,
                            sourceOutcome(paths, activeNodeId)));
        }
    }

    private String sourceOutcome(WorkstreamPaths paths, String nodeInstanceId) throws Exception {
        var value = ledger.loadOpenGateForNode(paths, nodeInstanceId).result().get("source_outcome");
        if (value == null || String.valueOf(value).isBlank()) {
            throw new IllegalStateException("open gate is missing source_outcome: " + nodeInstanceId);
        }
        return String.valueOf(value);
    }

    private void emitDomainEvents(WorkstreamPaths paths, String nodeDefinitionId,
                                 String handlerType, String nodeInstanceId,
                                 NodeResult result) throws Exception {
        if (result.status() != NodeStatus.COMPLETED) {
            return;
        }
        String eventId = "domain-" + nodeInstanceId;

        var commonPayload = new LinkedHashMap<String, Object>();
        commonPayload.put("handler_type", handlerType);
        commonPayload.put("node_id", nodeDefinitionId);
        commonPayload.put("node_instance_id", nodeInstanceId);

        switch (handlerType) {
            case "contract.compile" -> {
                commonPayload.put("contract_id", result.result().getOrDefault("contract_id", ""));
                commonPayload.put("contract_status", result.result().getOrDefault("contract_status", ""));
                ledger.appendEvent(paths, eventId,
                        ContractEventTypes.COMPILATION_COMPLETED, commonPayload);
            }
            case "acceptance.failure_classify" -> {
                commonPayload.put("category", result.result().getOrDefault("category", ""));
                commonPayload.put("matched_rule", result.result().getOrDefault("matched_rule", ""));
                commonPayload.put("review_decision", result.result().getOrDefault("review_decision", ""));
                ledger.appendEvent(paths, eventId,
                        ContractEventTypes.FAILURE_CLASSIFIED, commonPayload);
            }
            default -> { /* no domain event for this handler type */ }
        }
    }

    private boolean attemptAutoRetry(WorkstreamPaths paths, NodeInstanceDocument node, NodeDefinition nodeDef) throws Exception {
        var outcome = outcomeMap(node.result());
        if (!outcome.isEmpty()) {
            var retryPolicy = text(outcome.get("retryPolicy"));
            if (!"AUTO_ALLOWED".equals(retryPolicy)) {
                return false;
            }
            var policy = RetryPolicyResolver.resolve(text(outcome.get("primaryReason")), nodeDef.config());
            return autoRetry(paths, node, policy);
        }
        var recoverable = node.result().get("acpx_failure.recoverable");
        if (!Boolean.TRUE.equals(recoverable)) {
            return false;
        }
        var reasonValue = node.result().getOrDefault("acpx_failure.reason", "");
        var reason = reasonValue instanceof String s ? s : String.valueOf(reasonValue);
        var policy = RetryPolicyResolver.resolve(reason, nodeDef.config());
        return autoRetry(paths, node, policy);
    }

    private boolean autoRetry(WorkstreamPaths paths, NodeInstanceDocument node, RetryPolicy policy) throws Exception {
        var countValue = node.result().getOrDefault("auto_retry_count", 0);
        var count = (countValue instanceof Number n) ? n.intValue() : 0;
        if (count >= policy.maxRetries()) {
            return false;
        }

        var delay = policy.delayForAttempt(count + 1);
        ledger.autoRetryNode(paths, node.nodeInstanceId(), delay);
        if (delay > 0) {
            Thread.sleep(delay);
        }
        return true;
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> outcomeMap(Map<String, Object> result) {
        var value = result.get("agent_execution_outcome");
        return value instanceof Map<?, ?> map ? (Map<String, Object>) map : Map.of();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private Boolean resolveNodeForExecution(WorkstreamPaths paths, NodeInstanceDocument node) throws Exception {
        return switch (node.status()) {
            case READY -> true;
            case RUNNING -> resolveRunningNode(paths, node);
            case BLOCKED, WAITING, COMPLETED, CREATED, SKIPPED, FAILED -> null;
        };
    }

    private Boolean resolveRunningNode(WorkstreamPaths paths, NodeInstanceDocument node) throws Exception {
        if (hasActiveQueuedAgentTask(paths, node)) {
            return null;
        }
        var latestExecution = ledger.latestNodeExecution(paths, node);
        if (latestExecution.isPresent()) {
            var execution = latestExecution.get();
            if (execution.status() == NodeExecutionStatus.RUNNING) {
                var pid = execution.pid() == null ? 0L : execution.pid();
                var alive = pid > 0 && ProcessHandle.of(pid).map(ProcessHandle::isAlive).orElse(false);
                if (alive) {
                    return null;
                }
                ledger.markNodeExecutionStale(paths, execution, "detected by runtime resume");
                recoverStaleRunningNode(paths, node, pid <= 0 ? "" : pid);
                return null;
            }
        }
        var pidValue = node.result().get("running_pid");
        if (pidValue instanceof Number number) {
            var pid = number.longValue();
            var alive = ProcessHandle.of(pid).map(ProcessHandle::isAlive).orElse(false);
            if (alive) {
                return null;
            }
            recoverStaleRunningNode(paths, node, pid);
            return null;
        }
        recoverStaleRunningNode(paths, node, "");
        return null;
    }

    private boolean hasActiveQueuedAgentTask(WorkstreamPaths paths, NodeInstanceDocument node) throws Exception {
        var taskId = node.result().get("queued_agent_task_id");
        if (taskId == null || String.valueOf(taskId).isBlank()) {
            return false;
        }
        return ledger.readAgentTask(paths, String.valueOf(taskId))
                .map(task -> task.status() == dev.dual.ledger.file.AgentTaskStatus.QUEUED
                        || task.status() == dev.dual.ledger.file.AgentTaskStatus.RUNNING)
                .orElse(false);
    }

    private void recoverStaleRunningNode(WorkstreamPaths paths, NodeInstanceDocument node, Object pid) throws Exception {
        // Close any in-flight agent run.json (transport never returned / process killed) to a
        // typed terminal executionAttempt+executionOutcome before the node/workflow transition.
        ledger.appendEvent(paths, "stale-running-" + node.nodeInstanceId() + "-" + System.currentTimeMillis(),
                "node_stale_running_detected", Map.of(
                        "node", node.nodeDefinitionId(),
                        "node_instance_id", node.nodeInstanceId(),
                        "previous_running_pid", pid,
                        "action", "move_to_recovery"
                ));
        staleRunningRecovery.recover(paths, "detected by runtime resume");
    }

}

package dev.dual.runtime;

import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowStatus;
import dev.dual.ledger.file.AgentTaskDocument;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowExecutionDocument;
import dev.dual.ledger.file.WorkflowExecutionStatus;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;
import dev.dual.runtime.handler.AgentRunMetadataFinalizer;
import dev.dual.runtime.handler.ArtifactContractValidator;
import dev.dual.runtime.handler.DecisionHandler;
import dev.dual.runtime.handler.GateHandler;
import dev.dual.runtime.handler.HandlerRegistry;
import dev.dual.runtime.handler.TaskHandler;

import java.util.ArrayList;

/**
 * Executes one queued AgentTask.
 *
 * Worker owns dispatch execution only. It claims the queued task, records a
 * NodeExecution, invokes the handler, validates the artifact contract, and then
 * returns the node result to the ledger router. It does not choose workflow
 * transitions and it does not decide goal satisfaction.
 */
public final class AgentWorker {
    private final WorkflowFileLedger ledger;
    private final HandlerRegistry handlers;
    private final ArtifactContractValidator artifactContractValidator;
    private final AgentRunMetadataFinalizer runMetadataFinalizer;

    public AgentWorker(WorkflowFileLedger ledger, HandlerRegistry handlers) {
        if (ledger == null) {
            throw new IllegalArgumentException("ledger is required");
        }
        if (handlers == null) {
            throw new IllegalArgumentException("handlers is required");
        }
        this.ledger = ledger;
        this.handlers = handlers;
        this.artifactContractValidator = new ArtifactContractValidator();
        this.runMetadataFinalizer = new AgentRunMetadataFinalizer();
    }

    public AgentWorkerResult runOne(WorkflowCommand command) throws Exception {
        var paths = new WorkstreamPaths(command.workspaceRoot(), new DualId(command.workstreamId()));
        var task = ledger.firstQueuedAgentTask(paths);
        if (task.isEmpty()) {
            var current = ledger.loadCurrent(paths);
            return new AgentWorkerResult(command.workstreamId(), "", "", current.status(), false, "no queued agent task");
        }
        return executeQueued(command, paths, task.get());
    }

    private AgentWorkerResult executeQueued(
            WorkflowCommand command,
            WorkstreamPaths paths,
            AgentTaskDocument task
    ) throws Exception {
        var definition = ledger.loadDefinition(paths);
        var current = ledger.loadCurrent(paths);
        var nodeDoc = ledger.loadNode(paths, task.nodeInstanceId());
        var nodeDefinition = definition.node(nodeDoc.nodeDefinitionId());
        if (nodeDoc.status() != NodeStatus.RUNNING) {
            return new AgentWorkerResult(command.workstreamId(), task.agentTaskId(), nodeDefinition.id(),
                    current.status(), false, "queued task node is not running: " + nodeDoc.status());
        }

        var workflowExecution = ledger.startWorkflowExecution(paths, current, "worker");
        var nodeExecutionIds = new ArrayList<String>();
        var finished = false;
        try {
            var result = executeAndRecord(command, paths, workflowExecution, nodeExecutionIds, task, nodeDoc, nodeDefinition);
            ledger.completeAndRoute(paths, definition, nodeDoc.nodeInstanceId(), result.status(), result.outcome(),
                    result.outputRefs(), result.result());
            var next = ledger.loadCurrent(paths);
            openWaitingGates(command, paths, definition, next);
            var active = activeNodeDefinitionId(paths, next);
            ledger.finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, workflowExecutionStatus(next.status()),
                    "worker completed " + nodeDefinition.id());
            finished = true;
            return new AgentWorkerResult(command.workstreamId(), task.agentTaskId(), active, next.status(), true,
                    result.status() == NodeStatus.COMPLETED ? "agent task completed" : "workflow stopped at " + result.status());
        } catch (Exception failure) {
            if (!finished) {
                ledger.finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, WorkflowExecutionStatus.FAILED,
                        failure.getMessage());
            }
            throw failure;
        }
    }

    private NodeResult executeAndRecord(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds,
            AgentTaskDocument task,
            NodeInstanceDocument nodeDoc,
            NodeDefinition nodeDefinition
    ) throws Exception {
        long pid = ProcessHandle.current().pid();
        var nodeExecution = ledger.startNodeExecution(paths, workflowExecution.workflowExecutionId(), nodeDoc, task, pid);
        task = ledger.markAgentTaskRunning(paths, task, nodeExecution.nodeExecutionId());
        nodeExecutionIds.add(nodeExecution.nodeExecutionId());
        ledger.markRunning(paths, nodeDoc.nodeInstanceId(), pid);
        var node = ledger.loadCoreNode(paths, nodeDoc.nodeInstanceId());
        try {
            var result = dev.dual.runtime.handler.EvidenceCollection.execute(command.workspaceRoot(),
                    command.workstreamId(), nodeDoc, () -> executeNode(command, nodeDefinition, node));
            result = artifactContractValidator.validate(
                    command.workspaceRoot(),
                    command.workstreamId(),
                    node.nodeInstanceId(),
                    nodeDefinition,
                    node.inputRefs(),
                    result
            );
            result = runMetadataFinalizer.finalizeNodeResult(command.workspaceRoot(), result);
            ledger.markAgentTaskFinished(paths, task, result);
            ledger.finishNodeExecution(paths, nodeExecution, result);
            return result;
        } catch (Exception nodeFailure) {
            ledger.markAgentTaskFailed(paths, task, nodeFailure);
            ledger.failNodeExecution(paths, nodeExecution, nodeFailure);
            throw nodeFailure;
        }
    }

    private NodeResult executeNode(WorkflowCommand command, NodeDefinition nodeDefinition, dev.dual.core.workflow.NodeInstance node)
            throws Exception {
        return switch (nodeDefinition.kind()) {
            case TASK -> handlers.task(nodeDefinition.handlerType())
                    .execute(new TaskHandler.TaskContext(command.workspaceRoot(), command.workstreamId(), nodeDefinition, node));
            case DECISION -> handlers.decision(nodeDefinition.handlerType())
                    .evaluate(new DecisionHandler.DecisionContext(command.workspaceRoot(), command.workstreamId(), nodeDefinition, node));
            case GATE -> throw new IllegalStateException("gate nodes are not agent tasks");
        };
    }

    private void openWaitingGates(
            WorkflowCommand command,
            WorkstreamPaths paths,
            dev.dual.core.workflow.WorkflowDefinition definition,
            dev.dual.ledger.file.WorkflowCurrentDocument current
    ) throws Exception {
        if (current.status() != WorkflowStatus.WAITING_FOR_HUMAN) {
            return;
        }
        for (var activeNodeId : current.activeNodeInstanceIds()) {
            var nodeDoc = ledger.loadNode(paths, activeNodeId);
            if (nodeDoc.kind() != NodeKind.GATE) {
                continue;
            }
            var nodeDefinition = definition.node(nodeDoc.nodeDefinitionId());
            var node = ledger.loadCoreNode(paths, activeNodeId);
            handlers.gate(nodeDefinition.handlerType())
                    .openOrInspect(new GateHandler.GateContext(
                            command.workspaceRoot(), command.workstreamId(), nodeDefinition, node,
                            sourceOutcome(paths, activeNodeId)));
        }
    }

    private String sourceOutcome(WorkstreamPaths paths, String nodeInstanceId) throws Exception {
        var value = ledger.loadOpenGateForNode(paths, nodeInstanceId).result().get("source_outcome");
        if (value == null || String.valueOf(value).isBlank()) {
            throw new IllegalStateException("open gate is missing source_outcome: " + nodeInstanceId);
        }
        return String.valueOf(value);
    }

    private String activeNodeDefinitionId(WorkstreamPaths paths, dev.dual.ledger.file.WorkflowCurrentDocument current)
            throws Exception {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return "";
        }
        return ledger.loadNode(paths, current.activeNodeInstanceIds().get(0)).nodeDefinitionId();
    }

    private static WorkflowExecutionStatus workflowExecutionStatus(WorkflowStatus status) {
        return switch (status) {
            case CREATED -> WorkflowExecutionStatus.CREATED;
            case RUNNING -> WorkflowExecutionStatus.STOPPED;
            case WAITING_FOR_HUMAN -> WorkflowExecutionStatus.WAITING_FOR_HUMAN;
            case WAITING_FOR_RECOVERY -> WorkflowExecutionStatus.WAITING_FOR_RECOVERY;
            case BLOCKED -> WorkflowExecutionStatus.BLOCKED;
            case COMPLETED -> WorkflowExecutionStatus.ENDED;
            case FAILED -> WorkflowExecutionStatus.FAILED;
        };
    }
}

