    static final class Transport extends AcpxAgentTransport {
        final Fixture f;
        final List<String> calls = new ArrayList<>(), prompts = new ArrayList<>(), obligations = new ArrayList<>();
        String recommendation = "READY_FOR_PRODUCT_REVIEW";
        String acceptanceFailure = "";
        boolean providerDenied;
        boolean failNodeCompletionWrite;
        Transport(Fixture f) { this.f = f; }
        @Override public AcpxRunResult runClaudeDesign(AcpxRunRequest request) throws java.io.IOException { return run(request); }
        @Override public AcpxRunResult runCodexDesignReview(AcpxRunRequest request) throws java.io.IOException { return run(request); }
        @Override AcpxRunResult runAgentResultCorrection(String agent, AcpxRunRequest request) { throw new AssertionError("fixture must supply valid output first time"); }
        AcpxRunResult run(AcpxRunRequest request) throws java.io.IOException {
            try {
                var node = f.active();
                var runId = request.promptPath().getParent().getParent().getFileName().toString();
                var id = node.nodeDefinitionId();
                calls.add(id); prompts.add(Files.readString(request.promptPath()));
                var emission = AgentResultPromptContract.ProposalEmissionContext.initial();
                TaskContractRevisionContextResolver.Context revision = null;
                if (id.equals("intake.claude_brainstorm")) {
                    var resolved = new TaskContractRevisionContextResolver().resolveForNode(f.root, f.ws, node.nodeInstanceId());
                    assertTrue(resolved.valid(), resolved.errors().toString());
                    revision = resolved.context();
                    if (revision.revision()) emission = AgentResultPromptContract.proposalEmissionContext(revision);
                }
                var decision = switch (id) {
                    case "intake.claude_brainstorm" -> "READY_FOR_PRODUCT_REVIEW";
                    case "intake.codex_product_review" -> recommendation;
                    case "plan.claude_plan" -> "READY_FOR_PLAN_REVIEW";
                    case "plan.codex_plan_review" -> "READY_TO_IMPLEMENT";
                    case "implement.claude_implement" -> "IMPLEMENTED";
                    case "implement.claude_self_test_report" -> "SELF_TEST_COMPLETE";
                    case "acceptance.codex_verifier_review" -> acceptanceFailure.isEmpty() ? "ACCEPT" : "REJECT";
                    case "stage.claude_handoff" -> "HANDOFF_READY";
                    default -> "READY_FOR_ARCH_REVIEW";
                };
                var example = AgentResultPromptContract.render(f.ws, runId, id, decision, Set.of(decision), emission);
                var envelope = (ObjectNode) JSON.readTree(example.substring(example.lastIndexOf("\n{") + 1));
                var result = (ObjectNode) envelope.get("result");
                if (result.has("must_fix")) result.putArray("must_fix");
                if (result.has("contract_obligations")) result.putArray("contract_obligations");
                if (id.equals("acceptance.codex_verifier_review") && decision.equals("REJECT")) {
                    result.put("blocking", true);
                    result.putArray("missing_evidence").add("Operator must supply the unavailable verification record");
                    var failure = (ObjectNode) result.get("failure");
                    failure.put("category_hint", acceptanceFailure);
                    failure.putArray("contract_gaps"); failure.putArray("out_of_scope_files");
                    failure.putArray("missing_tests"); failure.putArray("context_gaps");
                    failure.put("verification_remediation", "NONE");
                    failure.put("reason", "Required verification service is unavailable; no product changes requested");
                    if (acceptanceFailure.equals("CONTEXT_INSUFFICIENT"))
                        failure.putArray("context_gaps").add("Operator verification record is unavailable");
                    acceptanceFailure = "";
                }
                if (decision.equals("BLOCKED")) {
                    result.put("blocking", true);
                    result.putArray("must_fix").add("Clarify the acceptance wording");
                }
                if (decision.equals("NEEDS_REVISION")) {
                    result.put("blocking", true);
                    ((ObjectNode) result.get("failure")).putArray("contract_gaps").add("Clarify acceptance wording");
                    result.putArray("contract_obligations").addObject().put("id", "CO-1").put("text", "Clarify acceptance wording");
                    recommendation = "READY_FOR_PRODUCT_REVIEW";
                }
                if (result.has("design")) ((ObjectNode) result.at("/design/planned_files/0"))
                        .put("path", "README.md").put("operation", "MODIFY");
                if (result.has("plan")) ((ObjectNode) result.get("plan")).putArray("edit_files").add("README.md");
                if (id.equals("implement.claude_implement")) Files.writeString(f.root.resolve("README.md"), "Documented generic utility behavior\n");
                if (revision != null) {
                    if (!revision.revision()) {
                        ((ObjectNode) result.get("scope")).putArray("included").addObject().put("path", "README.md");
                        result.putArray("evidence_refs").add("README.md");
                    } else {
                        var patches = result.putArray("obligation_patches");
                        for (var obligation : revision.obligations()) {
                            obligations.add(obligation.text());
                            var patch = patches.addObject().put("review_obligation_id", obligation.id());
                            patch.putArray("resolved_by_clause_ids").add("AC-1");
                            patch.putArray("clause_changes").addObject().put("operation", "REPLACE")
                                    .put("section", "ACCEPTANCE_CRITERIA").put("id", "AC-1")
                                    .put("text", "The documented utility behavior is observable");
                            patch.putArray("scope_additions"); patch.putArray("evidence_ref_additions");
                        }
                    }
                }
                Files.writeString(request.stdoutPath(), "fixture transcript"); Files.writeString(request.stderrPath(), "");
                if (failNodeCompletionWrite) Files.createDirectory(Path.of(f.paths.nodeJson(node.nodeInstanceId()) + ".tmp"));
                var now = Instant.now();
                return new AcpxRunResult(now, now.plusMillis(1), List.of("fixture"), List.of(), null,
                        new AcpxPromptCompletion("fixture", "end_turn", envelope.toString()),
                        new ProcessResult("fixture", null, 0, ProcessUsability.EXITED_ZERO, 1, "", "", false, false),
                        providerDenied ? List.of(new dev.dual.core.execution.AdapterSignal(
                                dev.dual.core.execution.AdapterSignalType.RATE_LIMITED, "quota exhausted", 1)) : List.of());
            } catch (java.io.IOException e) { throw e; }
            catch (Exception e) { throw new java.io.IOException(e); }
        }
    }
}

package dev.dual.adapter.acpx;

import dev.dual.core.workflow.WorkflowStatus;
import dev.dual.runtime.*;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import java.nio.file.Path;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Same real pipeline and declared variants; only the external provider is replaced. */
class WorkflowFirstLifecycleSequenceTest {
    @TempDir Path root;

    @ParameterizedTest @ValueSource(booleans = {false, true})
    void providerFailureCannotPublishEvenWhenItReturnsAValidCandidate(boolean queued) throws Exception {
        var f = new HumanRequirementContinuationSequenceTest.Fixture(root, queued);
        f.transport.providerDenied = true;
        f.untilGate();
        assertEquals(WorkflowStatus.WAITING_FOR_RECOVERY, f.ledger.loadCurrent(f.paths).status());
        assertEquals(1, f.transport.calls.size());
        var outcome = (Map<?, ?>) f.active().result().get("agent_execution_outcome");
        assertEquals("rate_limited", outcome.get("primaryReason"));
        assertTrue(f.active().outputRefs().stream().noneMatch(ref -> ref.endsWith(".contract.json")),
                "failed provider execution must not publish a business sidecar");
        try (var files = java.nio.file.Files.walk(f.paths.workstreamDir().resolve("runs"))) {
            assertTrue(files.noneMatch(path -> path.toString().endsWith(".contract.json")));
        }
    }

    @ParameterizedTest @ValueSource(booleans = {false, true})
    void preparationStorageFailureStopsBeforeProviderAndRetainsTheException(boolean queued) throws Exception {
        var f = new HumanRequirementContinuationSequenceTest.Fixture(root, queued);
        java.nio.file.Files.writeString(f.paths.workstreamDir().resolve("runs"), "not a directory");
        f.untilGate();
        assertEquals(WorkflowStatus.WAITING_FOR_RECOVERY, f.ledger.loadCurrent(f.paths).status());
        assertTrue(f.transport.calls.isEmpty());
        assertTrue(f.active().outputRefs().isEmpty());
        assertEquals("INPUT_PREPARATION_FAILED", f.active().result().get("reason"));
        assertTrue(f.active().result().get("failure_code").toString().contains("Exception"));
    }

    @ParameterizedTest @ValueSource(booleans = {false, true})
    void publishedCandidateWithoutDurableCompletionCannotReachTheReviewerOnColdResume(boolean queued) throws Exception {
        var f = new HumanRequirementContinuationSequenceTest.Fixture(root, queued);
        f.transport.failNodeCompletionWrite = true;
        assertThrows(Exception.class, f::untilGate);
        assertEquals(1, f.transport.calls.size());
        var interrupted = f.active();
        try (var files = java.nio.file.Files.walk(f.paths.workstreamDir().resolve("runs"))) {
            assertTrue(files.anyMatch(path -> path.toString().endsWith(".contract.json")),
                    "the cut must occur after candidate publication");
        }
        assertNotEquals(dev.dual.core.workflow.NodeStatus.COMPLETED, interrupted.status());
        java.nio.file.Files.delete(Path.of(f.paths.nodeJson(interrupted.nodeInstanceId()) + ".tmp"));
        try { f.runtime().resume(new WorkflowCommand(f.root, f.ws)); }
        catch (Exception safelyStopped) { /* partial completion remains a recovery problem */ }
        if (queued) {
            try { new AgentWorker(f.ledger, f.handlers()).runOne(new WorkflowCommand(f.root, f.ws)); }
            catch (Exception safelyStopped) { /* no orphan dispatch */ }
        }
        assertEquals(1, f.transport.calls.size(), "a published file cannot authorize retry or a reviewer");
        assertFalse(f.transport.calls.contains("intake.codex_product_review"));
    }

    @ParameterizedTest @ValueSource(booleans = {false, true})
    void removedApprovedContractStopsTheNextAuthorBeforeProvider(boolean queued) throws Exception {
        var f = new HumanRequirementContinuationSequenceTest.Fixture(root, queued);
        f.untilGate();
        f.ledger.resolveOpenGate(f.paths, f.definition, "approve", "Approve reviewed requirements");
        f.untilGate();
        assertEquals("gate.contract_review", f.active().nodeDefinitionId());
        f.ledger.resolveOpenGate(f.paths, f.definition, "approve", "Approve this compiled contract");
        var contract = f.paths.workstreamDir().resolve("artifacts/task-contract.json");
        var approvedBytes = java.nio.file.Files.readAllBytes(contract);
        java.nio.file.Files.delete(contract);
        int before = f.transport.calls.size();
        f.untilGate();
        assertEquals(WorkflowStatus.WAITING_FOR_RECOVERY, f.ledger.loadCurrent(f.paths).status());
        assertEquals(before, f.transport.calls.size());
        assertTrue(f.active().outputRefs().isEmpty());
        assertTrue(f.active().result().containsKey("input_preparation_failure"));
        assertFalse(f.active().result().toString().contains("AGENT_RESULT_MISSING"));
        var recovery = dev.dual.ledger.file.RecoveryAssessment.from(f.active(), f.root, f.ws);
        assertEquals("input_preparation_failure", recovery.classification());
        assertFalse(recovery.retrySafe());
        var failedId = f.active().nodeInstanceId();
        java.nio.file.Files.write(contract, approvedBytes);
        f.ledger.retryActiveNode(f.paths, "The exact previously approved bytes have been restored");
        f.untilGate();
        assertEquals("gate.human_design_approval", f.active().nodeDefinitionId());
        assertEquals(dev.dual.core.workflow.NodeStatus.COMPLETED, f.ledger.loadNode(f.paths, failedId).status());
        assertEquals(before + 2, f.transport.calls.size(), "manual retry must reach the author and architecture reviewer");
    }

    @ParameterizedTest @ValueSource(booleans = {false, true})
    void unavailablePrerequisitesRequireHumanDispositionThenEvidenceReverification(boolean queued) throws Exception {
        for (var variant : List.of("small", "terminal-delivery", "contract", "full")) {
            for (var category : List.of("TOOL_LIMITATION", "CONTEXT_INSUFFICIENT")) {
                for (var action : List.of("collect_evidence", "revise")) {
                    var f = new HumanRequirementContinuationSequenceTest.Fixture(root.resolve(variant).resolve(category).resolve(action), queued, variant);
                    f.transport.acceptanceFailure = category;
                    for (var gate : List.of("gate.human_requirement_review", "gate.contract_review",
                            "gate.human_design_approval", "gate.human_plan_approval")) {
                        f.untilGate();
                        assertEquals(gate, f.active().nodeDefinitionId());
                        f.ledger.resolveOpenGate(f.paths, f.definition, "approve", "Approve the reviewed subject");
                    }
                    f.untilGate();
                    assertEquals("gate.human_implementation_repair", f.active().nodeDefinitionId(), category);
                    assertEquals(1, Collections.frequency(f.transport.calls, "implement.claude_implement"));
                    var source = java.nio.file.Files.readString(f.root.resolve("README.md"));
                    dev.dual.runtime.handler.EvidenceCollection.resolveGate(f.ledger, f.paths, f.definition,
                            action, action.equals("revise") ? "Repair the approved documentation to address the prerequisite"
                                    : "Prerequisite is now available; verify against the unchanged product");
                    f.untilGate();
                    assertEquals("gate.human_acceptance", f.active().nodeDefinitionId());
                    assertEquals(action.equals("revise") ? 2 : 1,
                            Collections.frequency(f.transport.calls, "implement.claude_implement"));
                    assertEquals(2, Collections.frequency(f.transport.calls, "implement.claude_self_test_report"));
                    assertEquals(2, Collections.frequency(f.transport.calls, "acceptance.codex_verifier_review"));
                    assertEquals(source, java.nio.file.Files.readString(f.root.resolve("README.md")));
                }
            }
        }
    }

    @ParameterizedTest @ValueSource(booleans = {false, true})
    void acceptedProductTraversesEveryGateAndTerminalPreventsNewExecution(boolean queued) throws Exception {
        for (var variant : List.of("small", "terminal-delivery", "contract", "full")) {
            var f = new HumanRequirementContinuationSequenceTest.Fixture(root.resolve(variant), queued, variant);
            var gates = new ArrayList<String>();
            for (int i = 0; i < 12; i++) {
                f.untilGate();
                var current = f.ledger.loadCurrent(f.paths);
                if (current.status() == WorkflowStatus.COMPLETED) break;
                assertEquals(WorkflowStatus.WAITING_FOR_HUMAN, current.status(), f.active().toString());
                gates.add(f.active().nodeDefinitionId());
                var action = f.active().nodeDefinitionId().equals("gate.human_next_stage_approval") ? "complete" : "approve";
                f.ledger.resolveOpenGate(f.paths, f.definition, action, "Accept the exact reviewed evidence");
            }
            assertEquals(WorkflowStatus.COMPLETED, f.ledger.loadCurrent(f.paths).status());
            var expectedGates = new ArrayList<>(List.of("gate.human_requirement_review", "gate.contract_review",
                    "gate.human_design_approval", "gate.human_plan_approval", "gate.human_acceptance"));
            if (List.of("contract", "full").contains(variant)) expectedGates.add("gate.human_next_stage_approval");
            assertEquals(expectedGates, gates);
            assertEquals(!variant.equals("small"), f.transport.calls.contains("plan.codex_plan_review"));
            assertTrue(f.transport.calls.containsAll(List.of("implement.claude_implement", "implement.claude_self_test_report",
                    "acceptance.codex_verifier_review")));
            int calls = f.transport.calls.size();
            var before = f.snapshot();
            f.runtime().resume(new WorkflowCommand(f.root, f.ws));
            if (queued) new AgentWorker(f.ledger, f.handlers()).runOne(new WorkflowCommand(f.root, f.ws));
            assertThrows(Exception.class, () -> f.ledger.retryActiveNode(f.paths, "cannot reopen terminal"));
            assertThrows(Exception.class, () -> f.ledger.resolveOpenGate(f.paths, f.definition, "approve", "cannot reapprove"));
            assertEquals(calls, f.transport.calls.size());
            assertEquals(before, f.snapshot(), "terminal operations cannot create execution or rewrite evidence");
        }
    }
}

